DO $$ BEGIN CREATE TYPE user_role AS ENUM ('super_admin','project_supervisor','investigator','encoder'); EXCEPTION WHEN duplicate_object THEN NULL; END $$; CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,role user_role NOT NULL,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_code text NOT NULL UNIQUE,petitioner_name text NOT NULL,address text NOT NULL,contact_number text NOT NULL,status text NOT NULL DEFAULT 'encoding',supervisor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS investigation_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,total_households integer NOT NULL DEFAULT 0,with_dcwd_connection integer NOT NULL DEFAULT 0,without_dcwd_connection integer NOT NULL DEFAULT 0,existing_water_source text,findings text,encoded_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT investigation_household_counts CHECK (total_households >= 0 AND with_dcwd_connection >= 0 AND without_dcwd_connection >= 0 AND with_dcwd_connection + without_dcwd_connection = total_households)); CREATE TABLE IF NOT EXISTS project_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,blob_key text NOT NULL UNIQUE,file_name text NOT NULL,content_type text NOT NULL,uploaded_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS projects_status_idx ON projects(status); CREATE INDEX IF NOT EXISTS projects_supervisor_idx ON projects(supervisor_id); CREATE INDEX IF NOT EXISTS investigation_project_idx ON investigation_results(project_id); CREATE INDEX IF NOT EXISTS attachments_project_idx ON project_attachments(project_id);